#!/bin/bash
# Run by mitigate.py over SSH. All substitutions are generated by the runner.
set -Eeuo pipefail
umask 077
TARGET=/etc/php.ini.d/K000163821.ini
LOCK=/var/run/K000163821.lock
MODE=@@MODE@@
REQUIRE_SAM=@@SAM@@
EXPECTED=@@SHA256@@
CONTENT=@@CONTENT@@
stage=preflight
changed=false
installed=false
lock_owned=false
workdir=
staged=
error_code=
services=(httpd)
SERVICE_TIMEOUT=45
HEALTH_TIMEOUT=30
STOP_TIMEOUT=15
EXIT_TIMEOUT=10
httpd_recovery_attempts=0
httpd_initially_running=true

emit() { printf 'F5JOB\t%s\t%s\n' "$1" "$2"; }
step() { stage=$1; emit stage "$stage"; }
cleanup() {
    if [[ -n "$staged" ]]; then rm -f -- "$staged"; fi
    if [[ -n "$workdir" ]]; then rm -f -- "$workdir/candidate.ini"; fi
    if [[ "$lock_owned" == true ]]; then rmdir -- "$LOCK"; fi
}
trap cleanup EXIT
healthy() {
    local output
    output=$(timeout -k 5s 5s bigstart status "$1" 2>/dev/null) || return 1
    printf '%s\n' "$output" | running_line "$1"
}
running_line() {
    # BIG-IP uses both daemontools and SysV-style status lines.
    grep -Eq "^[[:space:]]*$1[[:space:]]+(run[[:space:]]+\\(pid[[:space:]]+[0-9]+\\)|\\(pid[[:space:]]+[0-9]+\\)[[:space:]]+is[[:space:]]+running([.[:space:]]|$))"
}
wait_healthy() {
    local deadline=$((SECONDS + HEALTH_TIMEOUT))
    while :; do
        if healthy "$1"; then return 0; fi
        (( SECONDS < deadline )) || return 1
        sleep 2
    done
}
httpd_gone() {
    local deadline=$((SECONDS + EXIT_TIMEOUT)) rc
    while :; do
        if timeout -k 5s 5s pgrep -x httpd >/dev/null 2>&1; then
            (( SECONDS < deadline )) || return 1
            sleep 1
        else
            rc=$?
            [[ "$rc" == 1 ]] && return 0
            return 1
        fi
    done
}
recover_httpd() {
    local rc
    httpd_recovery_attempts=$((httpd_recovery_attempts + 1))
    emit httpd_recovery_attempts "$httpd_recovery_attempts"
    emit httpd_recovery attempted
    # Stop first, but do not let a stuck service-control command block recovery.
    timeout -k 5s "${STOP_TIMEOUT}s" bigstart stop httpd >/dev/null 2>&1 || :
    # Exact process name only: never match httpd_sam/httpd_apm or shell arguments.
    if timeout -k 5s 5s pkill -KILL -x httpd >/dev/null 2>&1; then
        emit httpd_force_killed true
    else
        rc=$?
        if [[ "$rc" != 1 ]]; then emit httpd_recovery failed; return 1; fi
        # Exit 1 means no matching process; an already-stopped service still starts.
    fi
    if ! httpd_gone; then emit httpd_recovery failed; return 1; fi
    if timeout -k 5s "${SERVICE_TIMEOUT}s" bigstart start httpd >/dev/null 2>&1 && wait_healthy httpd; then
        emit httpd_recovery recovered
        return 0
    fi
    emit httpd_recovery failed
    return 1
}
restart_service() {
    if timeout -k 5s "${SERVICE_TIMEOUT}s" bigstart restart "$1" >/dev/null 2>&1 && wait_healthy "$1"; then
        return 0
    fi
    # Forced recovery is limited to the management httpd daemon.
    [[ "$1" == httpd ]] || return 1
    recover_httpd
}
verify_php() {
    # This verifies the CLI's normal ini scan and effective settings, not an
    # HTTP endpoint. No diagnostic PHP file is placed in a web-accessible path.
    php -r '
        $files = array_map("trim", explode(",", (string)php_ini_scanned_files()));
        if (!in_array("/etc/php.ini.d/K000163821.ini", $files, true)) exit(2);
        $expected = array("memory_limit" => "-1", "post_max_size" => "8M",
                          "upload_max_filesize" => "7M");
        foreach ($expected as $key => $value) {
            if (strcasecmp(trim(ini_get($key)), $value) !== 0) exit(3);
        }
        $progress = ini_get("session.upload_progress.enabled");
        if ($progress === false || !in_array(strtolower(trim($progress)), array("", "0", "off", "false"), true)) exit(4);
    ' >/dev/null 2>&1
}
fail() { error_code=$1; return 1; }
on_error() {
    local rc=$? rollback_ok=true service
    [[ "$rc" != 0 ]] || rc=1
    # Command substitutions inherit ERR with errtrace. Only the owning shell
    # may roll back; a failed status probe must just return its exit status.
    if (( BASH_SUBSHELL > 0 )); then exit "$rc"; fi
    trap - ERR HUP INT TERM
    set +e
    emit error "${error_code:-remote_command_failed}"
    emit failed_stage "$stage"
    if [[ "$installed" == true ]]; then
        emit stage rollback
        if [[ -f "$workdir/original.ini" ]]; then
            staged=$(mktemp /etc/php.ini.d/.K000163821.XXXXXXXX) &&
                cp -p -- "$workdir/original.ini" "$staged" &&
                mv -f -- "$staged" "$TARGET"
            [[ $? == 0 ]] || rollback_ok=false
        else
            rm -f -- "$TARGET" || rollback_ok=false
        fi
        for service in "${services[@]}"; do
            restart_service "$service" || rollback_ok=false
        done
        if [[ "$rollback_ok" == true ]]; then
            emit status failed_rolled_back
        else
            emit status failed_rollback_incomplete
        fi
    else
        emit status failed
    fi
    emit changed "$changed"
    emit script_exit_code "$rc"
    exit "$rc"
}
trap on_error ERR HUP INT TERM
emit stage preflight
[[ $(id -u) == 0 ]] || fail root_required
[[ -f /VERSION ]] && grep -q 'BIG-IP' /VERSION || fail not_bigip
[[ -d /etc/php.ini.d && ! -L /etc/php.ini.d ]] || fail ini_directory_missing_or_symlink
[[ ! -L "$TARGET" ]] || fail target_is_symlink
[[ ! -e "$TARGET" || -f "$TARGET" ]] || fail target_not_regular
for command in bigstart php sha256sum base64 mktemp install timeout; do
    command -v "$command" >/dev/null || fail missing_required_command
done
# Query services directly: the aggregate inventory omits SysV services on
# some BIG-IP releases. Unknown-service responses may themselves exit zero.
if [[ "$MODE" == apply ]]; then
    for command in pkill pgrep; do command -v "$command" >/dev/null || fail missing_required_command; done
fi
emit httpd_recovery not_needed
emit httpd_recovery_attempts 0
emit httpd_force_killed false
if ! healthy httpd; then
    [[ "$MODE" == apply ]] || fail required_service_not_running
    httpd_initially_running=false
fi
emit httpd_sam_state unknown
emit httpd_sam_decision blocked
sam_line=$(timeout -k 5s 10s bigstart status httpd_sam 2>&1) || fail service_discovery_failed
if [[ "$sam_line" == "Couldn't find service: httpd_sam" ]]; then
    sam_state=absent
elif [[ "$sam_line" == *$'\n'* ]]; then
    fail httpd_sam_status_ambiguous
elif printf '%s\n' "$sam_line" | running_line httpd_sam; then
    sam_state=running
elif printf '%s\n' "$sam_line" | grep -Eq '^[[:space:]]*httpd_sam[[:space:]]+(down|disabled)([[:space:],]|$)'; then
    sam_state=stopped
else
    fail httpd_sam_status_unrecognized
fi
emit httpd_sam_state "$sam_state"
if [[ "$sam_state" == running ]]; then
    services+=(httpd_sam)
    if [[ "$MODE" == apply ]]; then emit httpd_sam_decision restart; else emit httpd_sam_decision check; fi
elif [[ "$REQUIRE_SAM" == true ]]; then
    fail expected_httpd_sam_not_running
else
    emit httpd_sam_decision skip
fi
emit services "${services[*]}"

if [[ "$MODE" == apply ]]; then
    step lock
    mkdir -- "$LOCK" 2>/dev/null || fail device_locked
    lock_owned=true
    if [[ "$httpd_initially_running" == false ]]; then
        step recover_httpd
        recover_httpd || fail httpd_recovery_failed
    fi
fi
step inspect
current=absent
if [[ -f "$TARGET" ]]; then current=$(sha256sum "$TARGET" | awk '{print $1}'); fi
emit previous_sha256 "$current"
if [[ "$MODE" == check ]]; then
    if [[ "$current" == "$EXPECTED" ]] && verify_php; then
        emit status compliant
    else
        emit status needs_change
    fi
    emit changed false
    emit script_exit_code 0
    exit 0
fi

if [[ "$current" != "$EXPECTED" ]]; then
    step backup
    workdir=$(mktemp -d /var/tmp/K000163821.XXXXXXXX)
    if [[ -f "$TARGET" ]]; then
        cp -p -- "$TARGET" "$workdir/original.ini"
    else
        touch "$workdir/original_absent"
    fi
    emit backup "$workdir"
    step install
    printf '%s' "$CONTENT" | base64 -d > "$workdir/candidate.ini"
    [[ $(sha256sum "$workdir/candidate.ini" | awk '{print $1}') == "$EXPECTED" ]] || fail candidate_hash_mismatch
    # Stage on the target filesystem so the final rename is atomic.
    staged=$(mktemp /etc/php.ini.d/.K000163821.XXXXXXXX)
    if ! install -o root -g root -m 0644 "$workdir/candidate.ini" "$staged"; then
        rm -f -- "$staged"
        fail install_failed
    fi
    if ! mv -f -- "$staged" "$TARGET"; then rm -f -- "$staged"; fail install_failed; fi
    installed=true
    changed=true
    emit changed true
fi
step verify_php
verify_php || fail effective_php_settings_mismatch
step restart
# Repeated apply runs restart too: identical bytes alone cannot establish that
# a previous interrupted run reloaded Apache successfully.
for service in "${services[@]}"; do
    restart_service "$service" || fail service_restart_failed
done
step verify
[[ $(sha256sum "$TARGET" | awk '{print $1}') == "$EXPECTED" ]] || fail installed_hash_mismatch
verify_php || fail effective_php_settings_mismatch
emit sha256 "$EXPECTED"
emit changed "$changed"
emit status applied
emit stage complete
emit script_exit_code 0
